    h, w = len(grid), len(grid[0])
    objects = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                objects.setdefault(color, []).append((r, c))
    objs = []
    for color, cells in objects.items():
        r0 = min(r for r, c in cells); c0 = min(c for r, c in cells)
        r1 = max(r for r, c in cells); c1 = max(c for r, c in cells)
