            shape = [[int(grid[r0+i][c0+j] == color) for j in range(3)] for i in range(3)]
            objs.append((c0, color, shape))
    objs.sort()
    return [[(o[1] if o[2][r][c] else 0) for o in objs for c in range(3)] for r in range(3)]

